package io.nxmatic.rke2lab.osgibench.schema;

import org.osgi.service.metatype.annotations.AttributeDefinition;
import org.osgi.service.metatype.annotations.ObjectClassDefinition;
import org.osgi.service.metatype.annotations.RequireMetaTypeExtender;

/**
 * Disposable bench bundle that ships a Metatype OCD descriptor so a client can introspect its
 * config schema (keys/type/required) by PID, without knowing this provider. The descriptor is now
 * GENERATED by bnd from {@link ObjectClassDefinition} + {@link AttributeDefinition} on this
 * interface — the hand-written {@code OSGI-INF/metatype/*.xml} is gone. The {@code pid} element
 * makes bnd emit the {@code <Designate>} that binds the OCD to {@code
 * io.nxmatic.rke2lab.osgibench.incus} (the PID the introspection test reads), WITHOUT the
 * {@code @Designate} annotation — which would require a {@code @Component} and so pull in an {@code
 * osgi.component} extender this DS-free bench has no runtime for. {@link RequireMetaTypeExtender}
 * emits the {@code Require osgi.extender=osgi.metatype} the OCD descriptor genuinely depends on for
 * processing — the requirement the old bnd line typed by hand.
 */
@RequireMetaTypeExtender
public final class SchemaComponent {
  private SchemaComponent() {}

  @ObjectClassDefinition(
      id = "io.nxmatic.rke2lab.osgibench.incus",
      pid = "io.nxmatic.rke2lab.osgibench.incus",
      name = "Incus domain config")
  public @interface IncusConfig {
    @AttributeDefinition(name = "configDir", description = "Incus config directory (required)")
    String configDir();

    @AttributeDefinition(
        name = "project",
        description = "Incus project (optional)",
        required = false)
    String project();
  }
}
